    this.running = true;
    const me = await this.api('getMe').catch((e) => ({ ok: false, description: e.message }));
    if (!me.ok) { this.running = false; this.h.notice(`TLC bot: cannot connect (${safe(me.description, this.h.token)})`); return; }
    this.h.notice(`TLC bot @${me.result.username} is running`);
